package main

import (
	"fmt"
	"sync"
)

func worker(id int, wg *sync.WaitGroup) {
	defer wg.Done()           // signal completion when the function returns
	fmt.Printf("worker %d running\n", id)
}

func main() {
	var wg sync.WaitGroup     // zero value is ready to use
	for i := 1; i <= 3; i++ {
		wg.Add(1)             // increment the counter BEFORE starting the goroutine
		go worker(i, &wg)     // launch concurrently; pass i as an argument (no capture bug)
	}
	wg.Wait()                 // block until the counter returns to zero
	fmt.Println("all workers done")
}

package main

import (
	"fmt"
	"sync"
)

func main() {
	var wg sync.WaitGroup
	items := []string{"a", "b", "c"}
	for _, it := range items {
		wg.Add(1)
		it := it          // shadow: make a per-iteration copy (fix for Go <1.22)
		go func() {
			defer wg.Done()
			fmt.Println(it)  // prints a, b, c (each goroutine has its own it)
		}()
	}
	wg.Wait()
}
